class Solution {
  public int countQuadruples(String firstString, String secondString) {
    // a single character minimizes j - a: its first spot in one string and last spot in the other
    int[] first = new int[26], last = new int[26];
    java.util.Arrays.fill(first, -1);
    java.util.Arrays.fill(last, -1);
    for (int i = firstString.length() - 1; i >= 0; i--) first[firstString.charAt(i) - 'a'] = i;
    for (int i = 0; i < secondString.length(); i++) last[secondString.charAt(i) - 'a'] = i;
    int best = Integer.MAX_VALUE, count = 0;
    for (int c = 0; c < 26; c++) {
      if (first[c] < 0 || last[c] < 0) continue;
      int d = first[c] - last[c];
      if (d < best) {
        best = d;
        count = 1;
      } else if (d == best) count++;
    }
    return count;
  }
}
